arameter.value required=false multiplicity=one ] outputs=[ id="node-app-raster-1:document:out" port_id=document label=Document direction=out class=data form=value required=false multiplicity=one ] id=node-app-note-2 plugin-id=note app-id=document label="Note Board" yields="2d.note" document-ref=documents/node-app-note-2 config-ref=config/node-app-note-2 x=220 y=220 width=160 height=72 inputs=[ id="node-app-note-2:document:in" port_id=document label=Document direction=in class=data form=value required=false multiplicity=one ] outputs=[ id="node-app-note-2:document:out" port_id=document label=Document direction=out class=data form=value required=false multiplicity=one ] ] edges=[ id=edge-draw-1-to-draw-2 source-node-id=node-app-draw-1 source-port-id="node-app-draw-1:document:out" target-node-id=node-app-draw-2 target-port-id="node-app-draw-2:document:in"
